const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function initFraudMonitoring({root,call,back}){
 let signals=[],users=[],selected=null,query='',blockedOnly=false,busy=false,checkedAt='';
 function message(text){const field=document.querySelector('#safety-feedback');if(field)field.textContent=text;}
 async function search(){const result=await call('admin/users?q='+encodeURIComponent(query)+(blockedOnly?'&blocked=1':''));users=result.users;renderUsers();}
 async function show(){root.innerHTML='<p>Đang tải Fraud Monitoring…</p>';try{const result=await call('admin/fraud');signals=result.signals;checkedAt=result.checkedAt;selected=null;query='';blockedOnly=false;render();await search();}catch(error){root.innerHTML='<h1>Fraud Monitoring</h1><p id="safety-feedback" role="alert"></p><button id="safety-back">← Duyệt thẻ</button>';message(error.message);document.querySelector('#safety-back').onclick=back;}}
 function render(){root.innerHTML=`<section class="management-heading"><div><span class="eyebrow">COMMUNITY SAFETY</span><h1>Fraud Monitoring</h1><p>Phát hiện dấu hiệu cần xem xét. Mọi quyết định chặn do admin thực hiện.</p></div><button class="secondary" id="safety-back">← Duyệt thẻ</button></section><div class="safety-overview"><div><strong>${signals.length}</strong><span>Cảnh báo cần kiểm tra</span></div><div><strong>24 giờ</strong><span>Khoảng theo dõi gửi thẻ dồn dập</span></div><div><strong>Giấy tờ</strong><span>Chưa có dữ liệu · Chưa hỗ trợ tải giấy tờ</span></div></div><section class="safety-signals"><div class="safety-section-heading"><h2>Cảnh báo tự động</h2><small>Cập nhật: ${e(new Date(checkedAt).toLocaleString('vi-VN'))}</small></div><p class="safety-explainer">Trùng tên, tuổi hoặc số điện thoại có thể hợp lệ. Các dấu hiệu này không phải bằng chứng gian lận; không tự động chặn tài khoản. Hiện chỉ đối chiếu dữ liệu hồ sơ và thẻ đã gửi, chưa kiểm tra giấy tờ, chủ nợ hoặc hành vi thanh toán.</p><div class="safety-signal-grid">${signals.length?signals.map(s=>`<article class="safety-signal"><span class="status-badge">Cần xem xét</span><h3>${e(s.title)}</h3><p>${e(s.explanation)}</p><div>${s.members.map(member=>`<button class="secondary" data-signal-member="${e(member.id)}">${e(member.name)}${member.blocked?' · Đã chặn':''} ↗</button>`).join('')}</div></article>`).join(''):'<p class="safety-empty">Chưa phát hiện dấu hiệu trùng lặp hoặc gửi thẻ dồn dập theo các quy tắc hiện tại.</p>'}</div></section><section class="safety-members"><h2>Quản lý thành viên</h2><form id="safety-search"><label for="safety-query">Tìm tên thành viên, biệt danh hoặc email</label><div><input id="safety-query" name="query" type="search" maxlength="100" placeholder="Nhập tên thành viên…"><button>Tìm kiếm</button></div></form><label class="safety-block-filter"><input id="safety-blocked" type="checkbox"> Chỉ hiện tài khoản đã chặn</label><div class="safety-workspace"><div id="safety-user-list"></div><div id="safety-action-panel"><div class="review-placeholder"><h3>Chọn thành viên</h3><p>Xem lịch sử, gửi thông báo hoặc chặn tài khoản.</p></div></div></div></section><p id="safety-feedback" role="alert"></p>`;
 document.querySelector('#safety-back').onclick=()=>{if(!busy)back();};
 document.querySelector('#safety-search').onsubmit=async event=>{event.preventDefault();if(busy)return;query=document.querySelector('#safety-query').value.trim();selected=null;try{await search();document.querySelector('#safety-action-panel').innerHTML='';message('');}catch(error){message(error.message);}};
 document.querySelector('#safety-blocked').onchange=async event=>{if(busy){event.target.checked=blockedOnly;return;}blockedOnly=event.target.checked;try{await search();}catch(error){message(error.message);}};
 root.querySelectorAll('[data-signal-member]').forEach(button=>button.onclick=async()=>{if(busy)return;query=button.dataset.signalMember;document.querySelector('#safety-query').value=query;try{await search();await select(users.find(user=>user.id===query));document.querySelector('#safety-members-title')?.focus();}catch(error){message(error.message);}});
 }
 function renderUsers(){const shown=users.filter(user=>!blockedOnly||user.blocked);document.querySelector('#safety-user-list').innerHTML=shown.length?shown.map(user=>`<button class="safety-user ${selected?.id===user.id?'selected':''}" data-safety-user="${e(user.id)}"><strong>${e(user.name)}</strong><small>${e(user.email||user.nickname)}</small><span class="status-badge ${user.blocked?'rejected':'approved'}">${user.blocked?'Đã chặn':'Hoạt động'}</span>${user.protected?'<small>Tài khoản admin · được bảo vệ</small>':''}</button>`).join(''):'<p class="safety-empty">Không có thành viên phù hợp. Tối đa 100 kết quả mỗi lần tìm kiếm.</p>';root.querySelectorAll('[data-safety-user]').forEach(button=>button.onclick=()=>{if(!busy)select(users.find(user=>user.id===button.dataset.safetyUser));});}
 async function select(user){if(!user)return;selected=user;renderUsers();const panel=document.querySelector('#safety-action-panel');panel.innerHTML=`<div class="safety-selected"><h3 id="safety-members-title" tabindex="-1">${e(user.name)}</h3><p>${e(user.email||user.nickname)}</p><small>ID: ${e(user.id)}</small><p>${user.blocked?`Đã chặn · ${e(user.blockReason)}`:'Tài khoản đang hoạt động.'}</p><form id="safety-actions"><label for="safety-message">Nội dung thông báo / lý do xử lý</label><textarea id="safety-message" maxlength="1000" required placeholder="Nhập thông báo cho thành viên hoặc lý do chặn / mở chặn…"></textarea><p class="member-help">Thông báo được lưu trong app, không gửi email hoặc SMS. Tài khoản bị chặn sẽ bị ngắt phiên đăng nhập và thẻ được ẩn khỏi trang quẹt. Thành viên sẽ thấy lý do khi thử đăng nhập.</p><div class="review-actions"><button type="submit" name="action" value="notify" class="secondary">Gửi thông báo</button><button type="submit" name="action" value="block" ${user.protected&&!user.blocked?'disabled':''}>${user.blocked?'Mở chặn':'Chặn người dùng'}</button></div></form><h4>Lịch sử xử lý</h4><div id="safety-history">Đang tải…</div></div>`;
 document.querySelector('#safety-actions').onsubmit=async event=>{event.preventDefault();if(busy)return;const action=event.submitter?.value,text=document.querySelector('#safety-message').value.trim();if(!text){message('Vui lòng nhập nội dung hoặc lý do xử lý.');return;}if(!['notify','block'].includes(action))return;busy=true;const buttons=[...event.target.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await call('admin/users/'+encodeURIComponent(user.id)+'/'+action,action==='notify'?{message:text}:{blocked:!user.blocked,reason:text});await search();const updated=users.find(u=>u.id===user.id);if(updated)await select(updated);else{selected=null;document.querySelector('#safety-action-panel').innerHTML='';}message(action==='notify'?'Đã gửi thông báo trong app cho '+user.name+'.':user.blocked?'Đã mở chặn. Thành viên cần đăng nhập lại.':'Đã chặn tài khoản và ẩn thẻ khỏi trang quẹt.');}catch(error){message(error.message);buttons.forEach(b=>b.disabled=false);}finally{busy=false;}};
 try{const {events}=await call('admin/users/'+encodeURIComponent(user.id)+'/history');if(selected?.id!==user.id)return;document.querySelector('#safety-history').innerHTML=events.length?events.map(event=>`<article class="safety-history-item"><strong>${({notify:'Gửi thông báo',block:'Chặn tài khoản',unblock:'Mở chặn'})[event.action]||e(event.action)}</strong><small>${e(new Date(event.createdAt).toLocaleString('vi-VN'))}</small><p>${e(event.reason)}</p></article>`).join(''):'<p>Chưa có lịch sử xử lý.</p>';}catch(error){if(selected?.id===user.id)document.querySelector('#safety-history').textContent=error.message;}
 }
 return {show};
}
